'use strict';
// Replace these illustrative entries with five real job posts before research testing.
const jobs = [
 {title:'Frontend Developer Intern',company:'Sample Studio',logo:'S',tint:'#e8e7ff',ink:'#5c50d5',salary:'800 GEL / month',hours:'Part-time · 20 hrs/week',deadline:'15 Nov 2026',requirements:'Basic HTML, CSS and JavaScript. Open to current university students.'},
 {title:'Junior Software Developer',company:'Example Technologies',logo:'E',tint:'#e0f5ed',ink:'#279b70',salary:'Not specified',hours:'Full-time · 40 hrs/week',deadline:'20 Nov 2026',requirements:'3 years of professional experience, Git and basic SQL.'},
 {title:'Business Analyst Intern',company:'Demo Partners',logo:'D',tint:'#fff0df',ink:'#d99438',salary:'600 GEL / month',hours:'Flexible · 15 hrs/week',deadline:'10 Nov 2026',requirements:'Excel, communication skills and interest in business processes.'},
 {title:'QA Tester Intern',company:'Sample Labs',logo:'L',tint:'#e2f1ff',ink:'#418fca',salary:'Unpaid',hours:'Part-time · 25 hrs/week',deadline:'30 Nov 2026',requirements:'Attention to detail, basic bug reporting and ability to test web applications.'},
 {title:'Data Assistant Intern',company:'Example Analytics',logo:'A',tint:'#ffebf1',ink:'#cc688d',salary:'1,000 GEL / month',hours:'Not specified',deadline:'25 Nov 2026',requirements:'Basic Excel and Python. Third-year students are welcome.'}
];
let choices=Array(jobs.length).fill(null);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(){
 const list=document.getElementById('cards');
 list.innerHTML=jobs.map((j,i)=>{const choice=choices[i];return `<article class="job-card ${choice?'decided':''}" style="--tint:${j.tint};--ink:${j.ink}"><div class="card-top"><div class="company-logo" aria-hidden="true">${esc(j.logo)}</div><span class="card-number">0${i+1} / 05</span></div><div class="company">${esc(j.company)}</div><h2>${esc(j.title)}</h2><div class="detail-grid"><div class="detail"><span class="key">SALARY</span><span class="val">${esc(j.salary)}</span></div><div class="detail"><span class="key">WORKING HOURS</span><span class="val">${esc(j.hours)}</span></div><div class="detail"><span class="key">APPLICATION DEADLINE</span><span class="val">${esc(j.deadline)}</span></div><div class="detail"><span class="key">ROLE TYPE</span><span class="val">${j.title.includes('Intern')?'Internship':'Junior role'}</span></div></div><div class="requirements"><span class="key">REQUIREMENTS</span><p>${esc(j.requirements)}</p></div><div class="actions"><button type="button" class="skip ${choice==='skip'?'selected':''}" data-index="${i}" data-choice="skip" ${choice&&choice!=='skip'?'disabled':''} aria-label="Skip ${esc(j.title)}">${choice==='skip'?'✓ Skipped':'✕ Skip'}</button><button type="button" class="apply ${choice==='apply'?'selected':''}" data-index="${i}" data-choice="apply" ${choice&&choice!=='apply'?'disabled':''} aria-label="Apply to ${esc(j.title)}">${choice==='apply'?'✓ Applied':'✓ Apply'}</button></div>${choice?`<div class="decision-label">Decision recorded: ${choice==='apply'?'Apply':'Skip'}</div>`:''}</article>`}).join('');
 const completed=choices.filter(Boolean).length;document.getElementById('progressLabel').textContent=`${completed} of ${jobs.length} reviewed`;document.getElementById('progressPercent').textContent=`${Math.round(completed/jobs.length*100)}%`;document.getElementById('progressFill').style.width=`${completed/jobs.length*100}%`;
 const finished=completed===jobs.length;document.getElementById('finish').hidden=!finished;if(finished)document.getElementById('summary').textContent=`${choices.filter(x=>x==='apply').length} Apply · ${choices.filter(x=>x==='skip').length} Skip`;
}
document.getElementById('cards').addEventListener('click',e=>{const button=e.target.closest('button[data-choice]');if(!button)return;const i=Number(button.dataset.index);const next=button.dataset.choice;choices[i]=choices[i]===next?null:next;render()});
document.getElementById('reset').addEventListener('click',()=>{choices=Array(jobs.length).fill(null);render();window.scrollTo({top:0,behavior:'smooth'})});
render();
